SPARQL:
SELECT DISTINCT ?item ?itemLabel ?elev WHERE {
  ?item wdt:P31/wdt:P279* wd:Q8502;
        wdt:P2044 ?elev.
  { ?item wdt:P30 wd:Q49 } UNION { ?item wdt:P17/wdt:P30 wd:Q49 }.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?elev)
OFFSET 6
LIMIT 1

SELECT ?item ?itemLabel WHERE {
  wd:Q1258 wdt:P161 ?item.
  ?item wdt:P19 wd:Q65.
  ?item wdt:P31 wd:Q5.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?actor ?actorLabel WHERE {
  ?film wdt:P31 wd:Q11424;
        rdfs:label "Vanilla Sky"@en;
        wdt:P161 ?actor.
  ?actor wdt:P26 wd:Q13133.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT (MIN(YEAR(?pub)) AS ?year) WHERE {
  ?series rdfs:label "A Song of Ice and Fire"@en.
  ?book wdt:P179 ?series;
        wdt:P1545 ?ord;
        wdt:P577 ?pub.
  FILTER(xsd:integer(?ord) = 1)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person ?personLabel ?stateLabel ?dob WHERE {
  ?state wdt:P31 wd:Q35657;
         wdt:P6 ?person.
  ?person wdt:P31 wd:Q5;
          wdt:P569 ?dob.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?dob)
LIMIT 1

SELECT ?president ?presidentLabel ?votes WHERE {
  ?election wdt:P541 wd:Q11696.
  ?election p:P726 ?candStmt.
  ?candStmt ps:P726 ?president.
  ?president wdt:P39 wd:Q11696.
  ?candStmt pq:P1111 ?votes.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?votes)
LIMIT 1

SELECT (EXISTS { wd:Q359442 wdt:P39 wd:Q11696 } AS ?hasBeenPresident) WHERE {
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?actor ?actorLabel WHERE {
  VALUES ?actor { wd:Q2685 }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?age ?winDate WHERE {
  VALUES ?person { wd:Q26876 }
  ?person wdt:P569 ?birth .
  ?person p:P166 ?awardStmt .
  ?awardStmt ps:P166 ?award ;
             pq:P585 ?winDate .
  ?award wdt:P31/wdt:P279* wd:Q41207 .
  BIND(
    YEAR(?winDate) - YEAR(?birth)
    - IF(
        (MONTH(?winDate) < MONTH(?birth)) ||
        (MONTH(?winDate) = MONTH(?birth) && DAY(?winDate) < DAY(?birth)),
        1, 0
      ) AS ?age
  )
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?winDate
LIMIT 1

SELECT DISTINCT ?river ?riverLabel WHERE {
  wd:Q1497 wdt:P2043 ?missLen.
  ?river wdt:P31 wd:Q4022;
         wdt:P2043 ?length.
  FILTER(?river != wd:Q1497)
  FILTER(?length > ?missLen)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?singer ?singerLabel ?age WHERE {
  ?song wdt:P31 wd:Q7366;
        rdfs:label "The Dance"@en;
        wdt:P175 ?singer.
  ?singer wdt:P31 wd:Q5;
          wdt:P569 ?dob.
  OPTIONAL { ?singer wdt:P570 ?dod. }
  BIND(COALESCE(?dod, NOW()) AS ?refDate)
  BIND(YEAR(?refDate) - YEAR(?dob) - IF(MONTH(?refDate) < MONTH(?dob) || (MONTH(?refDate) = MONTH(?dob) && DAY(?refDate) < DAY(?dob)), 1, 0) AS ?age)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?state ?stateLabel ?admission WHERE {
  ?state wdt:P31 wd:Q35657;
         wdt:P571 ?admission.
  FILTER(?state != wd:Q782)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?admission)
LIMIT 1

SELECT ?lake ?lakeLabel ?length WHERE {
  ?lake wdt:P31/wdt:P279* wd:Q23397.
  ?lake wdt:P2043 ?length.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?length)
LIMIT 1

SELECT (COUNT(DISTINCT ?team) AS ?teamCount) WHERE {
  ?person rdfs:label "Matthew Stafford"@en;
          wdt:P31 wd:Q5;
          wdt:P54 ?team.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?singer ?singerLabel ?birthplace ?birthplaceLabel WHERE {
  ?song rdfs:label "Genie in a Bottle"@en;
        wdt:P31 ?type;
        wdt:P175 ?singer.
  VALUES ?type { wd:Q7366 wd:Q134556 }
  ?singer wdt:P19 ?birthplace.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?album ?albumLabel (MIN(?d) AS ?date) WHERE {
  ?album wdt:P31/wdt:P279* wd:Q208569;
         wdt:P175 wd:Q11649;
         wdt:P577 ?d.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?album ?albumLabel
ORDER BY ASC(?date)
OFFSET 3
LIMIT 1

SELECT ?series ?seriesLabel ?firstRelease WHERE {
  VALUES ?seedLabel { "Metroid"@en "Super Mario Bros."@en }
  ?seedGame rdfs:label ?seedLabel;
            wdt:P31 wd:Q7889;
            wdt:P179 ?series.
  {
    SELECT ?series (MIN(?date) AS ?firstRelease) WHERE {
      ?game wdt:P179 ?series;
            wdt:P31 wd:Q7889;
            wdt:P577 ?date.
    } GROUP BY ?series
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?firstRelease
LIMIT 2

SELECT ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q7889.
  ?item rdfs:label ?label.
  FILTER(LANG(?label) = "en").
  FILTER(CONTAINS(?label, "Super Mario Land")).
  FILTER NOT EXISTS { ?item wdt:P674 wd:Q1406. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?isLargest ?texas ?texasLabel ?largestState ?largestStateLabel ?txArea ?maxArea WHERE {
  BIND(wd:Q1439 AS ?texas)
  ?texas wdt:P2046 ?txArea.
  {
    SELECT (MAX(?area) AS ?maxArea) WHERE {
      ?s wdt:P31 wd:Q35657;
         wdt:P2046 ?area.
    }
  }
  OPTIONAL {
    ?largestState wdt:P31 wd:Q35657;
                  wdt:P2046 ?maxArea.
  }
  BIND(IF(?txArea = ?maxArea, true, false) AS ?isLargest)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT (COUNT(DISTINCT ?ws) AS ?count) WHERE {
  VALUES ?team { wd:Q1155894 wd:Q171582 wd:Q467426 }
  ?ws wdt:P629 wd:Q81021;
      wdt:P1346 ?winner.
  FILTER(?winner != ?team)
  { ?ws wdt:P710 ?team } UNION { ?ws wdt:P1923 ?team }.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?person ?personLabel WHERE {
  wd:Q414 p:P6 ?statement.
  ?statement ps:P6 ?person;
             pq:P580 ?start;
             pq:P582 ?end.
  FILTER(YEAR(?start) = 1989 && YEAR(?end) = 1999)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q5;
        wdt:P19 wd:Q5092;
        wdt:P21 wd:Q6581097;
        wdt:P27 wd:Q30;
        wdt:P1344 ?event.
  ?event (wdt:P361*) ?parentEvent.
  ?parentEvent rdfs:label "Swimming at the 2004 Summer Olympics"@en.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT (IF(COUNT(?sb) > 0, "Yes", "No") AS ?wonSinceReturn) WHERE {
  ?team rdfs:label "Los Angeles Rams"@en.
  {
    SELECT ?team (MAX(?start) AS ?returnDate) WHERE {
      ?team p:P159 ?st.
      ?st ps:P159 ?city.
      ?city rdfs:label "Los Angeles"@en.
      OPTIONAL { ?st pq:P580 ?start. }
    } GROUP BY ?team
  }
  ?sb wdt:P1346 ?team.
  ?sb wdt:P179 ?series.
  ?series rdfs:label "Super Bowl"@en.
  ?sb wdt:P585 ?date.
  FILTER(?date >= ?returnDate)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?person ?personLabel ?start ?end WHERE {
  BIND(wd:Q1397 AS ?state)
  ?state wdt:P1313 ?office.
  ?person p:P39 ?posStmt.
  ?posStmt ps:P39 ?office.
  OPTIONAL { ?posStmt pq:P580 ?start. }
  OPTIONAL { ?posStmt pq:P582 ?end. }
  BIND("2000-01-01T00:00:00Z"^^xsd:dateTime AS ?cutoff)
  FILTER( (BOUND(?end) && ?end >= ?cutoff) || (!BOUND(?end) && BOUND(?start) && ?start >= ?cutoff) )
  FILTER NOT EXISTS { ?person wdt:P102 wd:Q29468. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?start

SELECT ?count (IF(?count=0, true, false) AS ?noOne) WHERE {
  {
    SELECT (COUNT(DISTINCT ?person) AS ?count) WHERE {
      ?person wdt:P39 ?pos.
      ?pos wdt:P194 wd:Q11268.
      ?person wdt:P140/wdt:P279* wd:Q5043.
    }
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?isVenusOlder WHERE {
  ?venus wdt:P31 wd:Q5;
         rdfs:label "Venus Williams"@en;
         wdt:P569 ?venusBirth.
  ?serena wdt:P31 wd:Q5;
          rdfs:label "Serena Williams"@en;
          wdt:P569 ?serenaBirth.
  BIND(?venusBirth < ?serenaBirth AS ?isVenusOlder)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?rubberSoul ?rubberSoulLabel ?rubberSoulDate ?revolver ?revolverLabel ?revolverDate (?rubberSoulDate < ?revolverDate AS ?rubberSoulBeforeRevolver) WHERE {
  ?beatles wdt:P31 wd:Q215380; rdfs:label "The Beatles"@en.

  {
    SELECT ?rubberSoul (MIN(?d1) AS ?rubberSoulDate) WHERE {
      ?rubberSoul wdt:P31 wd:Q208569;  # studio album
                  wdt:P175 ?beatles;
                  rdfs:label "Rubber Soul"@en;
                  wdt:P577 ?d1.
    } GROUP BY ?rubberSoul
  }

  {
    SELECT ?revolver (MIN(?d2) AS ?revolverDate) WHERE {
      ?revolver wdt:P31 wd:Q208569;  # studio album
                wdt:P175 ?beatles;
                rdfs:label "Revolver"@en;
                wdt:P577 ?d2.
    } GROUP BY ?revolver
  }

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?age WHERE {
  ?person wdt:P31 wd:Q5;
          rdfs:label "Aziz Ansari"@en;
          wdt:P569 ?dob.
  BIND(NOW() AS ?now)
  BIND((YEAR(?now) - YEAR(?dob) - IF(MONTH(?now) < MONTH(?dob) || (MONTH(?now) = MONTH(?dob) && DAY(?now) < DAY(?dob)), 1, 0)) AS ?age)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 1

SELECT (COUNT(?statement) AS ?count) WHERE {
  ?person wdt:P31 wd:Q5;
          rdfs:label "Colson Whitehead"@en;
          p:P166 ?statement.
  ?statement ps:P166 ?award.
  ?award wdt:P361 wd:Q42536.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person ?personLabel (COUNT(DISTINCT ?film) AS ?filmCount) WHERE {
  VALUES ?name {"Kevin Hart"@en "Dwayne Johnson"@en}
  ?person wdt:P31 wd:Q5;
          wdt:P106 wd:Q33999;
          rdfs:label ?name.
  ?film wdt:P31/wdt:P279* wd:Q11424;
        wdt:P161 ?person.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?person ?personLabel
ORDER BY DESC(?filmCount)

ASK WHERE {
  ?film wdt:P31 wd:Q11424;
        rdfs:label "Moana"@en;
        wdt:P577 ?date.
  ?film schema:description ?desc.
  FILTER(LANG(?desc) = "en" && CONTAINS(LCASE(?desc), "2016") && CONTAINS(LCASE(?desc), "film"))
  FILTER(?date < "2015-01-01T00:00:00Z"^^xsd:dateTime)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?film ?filmLabel (MAX(?usdAmount) AS ?boxOfficeUSD) WHERE {
  {
    ?film wdt:P31 wd:Q11424;
          rdfs:label "Joker"@en;
          wdt:P577 ?date.
    FILTER(YEAR(?date)=2019)
  }
  UNION
  {
    ?film wdt:P31 wd:Q11424;
          rdfs:label "Suicide Squad"@en;
          wdt:P577 ?date.
    FILTER(YEAR(?date)=2016)
  }
  ?film p:P2142 ?stmt.
  ?stmt psv:P2142 ?valNode.
  ?valNode wikibase:quantityAmount ?usdAmount;
           wikibase:quantityUnit wd:Q4917.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?film ?filmLabel
ORDER BY DESC(?boxOfficeUSD)
LIMIT 1

SELECT ?film ?filmLabel (MIN(?pubDate) AS ?firstRelease) WHERE {
  VALUES ?article { <https://en.wikipedia.org/wiki/Avengers:_Endgame> <https://en.wikipedia.org/wiki/Joker_(2019_film)> }
  ?article schema:about ?film .
  ?film wdt:P31 wd:Q11424 ;
        wdt:P577 ?pubDate .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?film ?filmLabel
ORDER BY ?firstRelease
LIMIT 1

ASK WHERE {
  {
    SELECT (MIN(YEAR(?d1)) AS ?y1) WHERE { wd:Q193603 wdt:P577 ?d1. }
  }
  {
    SELECT (MIN(YEAR(?d2)) AS ?y2) WHERE { wd:Q188543 wdt:P577 ?d2. }
  }
  FILTER(?y1 = ?y2)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX bd: <http://www.bigdata.com/rdf#>

SELECT ?film ?filmLabel (MIN(?date) AS ?firstRelease) (IF(MIN(?date) < "2000-01-01T00:00:00Z"^^xsd:dateTime, true, false) AS ?cameOutBefore2000) WHERE {
  ?film wdt:P31 wd:Q11424;
        rdfs:label "Screech"@en;
        wdt:P577 ?date.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?film ?filmLabel

SELECT ?person ?personLabel ?dob WHERE {
  VALUES ?person { wd:Q43466 wd:Q215152 }
  ?person wdt:P569 ?dob.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?dob
LIMIT 1

SELECT ?item ?itemLabel ?date WHERE {
  ?item wdt:P31 wd:Q11424;
        rdfs:label "The Ring"@en;
        wdt:P577 ?date.
  FILTER(?date < "2005-01-01T00:00:00Z"^^xsd:dateTime)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person ?personLabel ?birth WHERE {
  VALUES ?name {"Jodie Foster"@en "Julia Roberts"@en}
  ?person rdfs:label ?name;
          wdt:P31 wd:Q5;
          wdt:P569 ?birth.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ASC(?birth)
LIMIT 1

SELECT ?person ?personLabel ?height WHERE {
  VALUES ?person { wd:Q13909 wd:Q35332 }
  ?person wdt:P2048 ?height.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?height)
LIMIT 1

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX bd: <http://www.bigdata.com/rdf#>

SELECT ?jakeLabel ?maggieLabel ?jakeBirth ?maggieBirth ?isJakeOlder WHERE {
  ?jake wdt:P31 wd:Q5;
        rdfs:label "Jake Gyllenhaal"@en;
        wdt:P569 ?jakeBirth.
  ?maggie wdt:P31 wd:Q5;
          rdfs:label "Maggie Gyllenhaal"@en;
          wdt:P569 ?maggieBirth.
  BIND(?jakeBirth < ?maggieBirth AS ?isJakeOlder)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

ASK WHERE {
  ?film wdt:P31 wd:Q11424 ;
        wdt:P57 wd:Q146929 ;
        wdt:P577 ?date .
  FILTER(EXISTS { ?film rdfs:label "Parasite"@en })
  FILTER(?date > "2015-12-31T00:00:00Z"^^xsd:dateTime)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

ASK WHERE {
  ?film wdt:P31 wd:Q11424;
        rdfs:label "Citizen Kane"@en;
        wdt:P577 ?date.
  FILTER(?date < "1950-01-01T00:00:00Z"^^xsd:dateTime)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?year WHERE {
  wd:Q37079 wdt:P569 ?birthTom.
  wd:Q8646 wdt:P569 ?birthDenzel.
  FILTER(?birthTom > ?birthDenzel)
  BIND(YEAR(?birthTom) AS ?year)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?film ?filmLabel (MAX(?budget) AS ?budgetAmount) ((MAX(?budget) > 200000000) AS ?isOver200M) WHERE {
  ?film wdt:P31 wd:Q11424;
        rdfs:label "Avatar"@en;
        wdt:P577 ?date.
  FILTER(YEAR(?date) = 2009)
  { ?film wdt:P2769 ?budget } UNION { ?film wdt:P2130 ?budget }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?film ?filmLabel

SELECT ?film ?filmLabel ?boxOffice WHERE {
  {
    SELECT ?film (MAX(?amount) AS ?boxOffice) WHERE {
      VALUES ?film { wd:Q248 wd:Q44578 }
      ?film wdt:P2142 ?amount.
    }
    GROUP BY ?film
    ORDER BY DESC(?boxOffice)
    LIMIT 1
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?title ?boxOffice WHERE {
  VALUES ?title {"Jurassic World"@en "The Lion King"@en}
  {
    SELECT ?title (MAX(?box) AS ?boxOffice) WHERE {
      ?movie wdt:P31 wd:Q11424;
             wdt:P1476 ?title;
             wdt:P2142 ?box.
      FILTER(LANG(?title) = "en")
    }
    GROUP BY ?title
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?boxOffice)

SELECT ?item ?itemLabel (MAX(?value) AS ?views) (SAMPLE(?propLabel) AS ?metricLabel) WHERE {
  VALUES ?name { "Bridgerton"@en "Tiger King"@en "Tiger King: Murder, Mayhem and Madness"@en }
  ?item rdfs:label ?name;
        wdt:P31/wdt:P279* wd:Q5398426;
        wdt:P449 wd:Q907311.
  ?item ?wdtProp ?value .
  ?propEntity wikibase:directClaim ?wdtProp;
              wikibase:propertyType wikibase:Quantity;
              rdfs:label ?propLabel.
  FILTER(LANG(?propLabel) = "en")
  FILTER(
    CONTAINS(LCASE(?propLabel), "view") ||
    CONTAINS(LCASE(?propLabel), "viewer") ||
    CONTAINS(LCASE(?propLabel), "viewership") ||
    CONTAINS(LCASE(?propLabel), "household") ||
    CONTAINS(LCASE(?propLabel), "participants") ||
    CONTAINS(LCASE(?propLabel), "watch") ||
    CONTAINS(LCASE(?propLabel), "hours")
  )
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?item ?itemLabel
ORDER BY DESC(?views)
LIMIT 2
